-- Vygenerované tools/export-rules.mjs 2026-09-13

insert into public.rules (property_id, version, texts) values (null, '2026-09', '{"en":{"intro":"These rules keep the building safe and quiet for everyone. Breaking them can lead to a fine or the end of your stay. (Template based on standard PRIMA rules — the official text is available at reception.)","sections":[{"title":"Access and identity","items":["Only registered guests may stay in the building. Show your ID at check-in.","Your access card is personal. Do not lend it or let anyone in behind you at the turnstile.","Report a lost card immediately at reception."]},{"title":"Quiet hours","items":["22:00–06:00 is quiet time. No loud music, TV or gatherings in rooms or corridors.","Many guests sleep during the day after night shifts — keep noise low at all times."]},{"title":"Visitors","items":["Visitors must register at reception with an ID and may stay 08:00–22:00.","Overnight visitors are not allowed."]},{"title":"Rooms","items":["No smoking, candles, own heaters or hotplates in rooms.","Do not move furniture between rooms or change locks.","Report any defect through the app or at reception.","Let housekeeping in on working days; lock away your valuables."]},{"title":"Kitchen and cleanliness","items":["Cook only in the kitchen. Clean the cooker and your dishes right after use.","Sort waste and take it to the bins. Nothing may be stored in corridors.","Food in the shared fridge must be labelled with your room number."]},{"title":"Safety","items":["Do not cover smoke detectors or block emergency exits.","In case of fire, leave the building and call 150 or 112.","Alcohol is not allowed in common areas. Drunk or aggressive behaviour ends the stay."]},{"title":"Damage and fees","items":["Report damage immediately. Intentional damage is charged.","Lost card, lost key or extra cleaning may be charged according to the price list at reception."]},{"title":"Check-out","items":["Return the card and leave the room clean. Tell your coordinator and reception about the date in advance."]}],"version":"2026-09"},"ru":{"intro":"Эти правила делают здание безопасным и спокойным для всех. Их нарушение может привести к штрафу или прекращению проживания. (Шаблон на основе стандартных правил PRIMA — официальный текст доступен на ресепшене.)","sections":[{"title":"Доступ и личность","items":["В здании могут проживать только зарегистрированные жильцы. При заселении покажите документ.","Карта доступа — личная. Не одалживайте её и не пропускайте никого за собой через турникет.","О потере карты немедленно сообщите на ресепшен."]},{"title":"Тишина","items":["22:00–06:00 — время тишины. Никакой громкой музыки, телевизора или собраний в комнатах и коридорах.","Многие жильцы спят днём после ночных смен — не шумите в любое время."]},{"title":"Посетители","items":["Посетители регистрируются на ресепшене с документом и могут находиться с 08:00 до 22:00.","Ночёвка посетителей запрещена."]},{"title":"Комнаты","items":["В комнатах запрещено курить, пользоваться свечами, собственными обогревателями или плитками.","Не переносите мебель между комнатами и не меняйте замки.","О любой неисправности сообщите через приложение или на ресепшене.","В рабочие дни впускайте уборщиц; ценные вещи запирайте."]},{"title":"Кухня и чистота","items":["Готовьте только на кухне. Мойте плиту и посуду сразу после использования.","Сортируйте мусор и выносите его в контейнеры. В коридорах ничего не хранить.","Продукты в общем холодильнике подписывайте номером комнаты."]},{"title":"Безопасность","items":["Не закрывайте датчики дыма и не блокируйте аварийные выходы.","При пожаре покиньте здание и звоните 150 или 112.","Алкоголь в общих помещениях запрещён. Пьяное или агрессивное поведение прекращает проживание."]},{"title":"Ущерб и оплата","items":["Об ущербе сообщайте немедленно. Умышленное повреждение оплачивается.","Потерянная карта, ключ или дополнительная уборка могут оплачиваться по прейскуранту на ресепшене."]},{"title":"Выезд","items":["Верните карту и оставьте комнату чистой. Дату выезда заранее сообщите координатору и ресепшену."]}],"version":"2026-09"},"sk":{"intro":"Tieto pravidlá udržiavajú budovu bezpečnú a pokojnú pre všetkých. Ich porušenie môže znamenať pokutu alebo ukončenie pobytu. (Vzor podľa štandardných pravidiel PRIMA — oficiálny text je k dispozícii na recepcii.)","sections":[{"title":"Vstup a totožnosť","items":["V budove môžu bývať len registrovaní hostia. Pri ubytovaní ukážte doklad.","Prístupová karta je osobná. Nepožičiavajte ju a nepúšťajte nikoho za sebou cez turniket.","Stratu karty ihneď nahláste na recepcii."]},{"title":"Nočný kľud","items":["22:00–06:00 je čas kľudu. Žiadna hlasná hudba, TV ani stretnutia v izbách a na chodbách.","Mnohí hostia spia cez deň po nočnej — hluk držte nízko vždy."]},{"title":"Návštevy","items":["Návšteva sa registruje na recepcii s dokladom a môže sa zdržať 08:00–22:00.","Prenocovanie návštev nie je dovolené."]},{"title":"Izby","items":["V izbách sa nefajčí, nepoužívajú sviečky, vlastné ohrievače ani variče.","Nepresúvajte nábytok medzi izbami a nemeňte zámky.","Každú závadu nahláste cez appku alebo na recepcii.","V pracovné dni pustite chyžné do izby; cennosti si zamknite."]},{"title":"Kuchyňa a čistota","items":["Varte len v kuchyni. Sporák a riad umyte hneď po použití.","Trieďte odpad a noste ho do nádob. Na chodbách sa nič neskladuje.","Potraviny v spoločnej chladničke označte číslom izby."]},{"title":"Bezpečnosť","items":["Nezakrývajte hlásiče dymu a neblokujte únikové východy.","Pri požiari opustite budovu a volajte 150 alebo 112.","Alkohol nie je dovolený v spoločných priestoroch. Opité alebo agresívne správanie ukončuje pobyt."]},{"title":"Škody a poplatky","items":["Škodu hneď nahláste. Úmyselné poškodenie sa účtuje.","Stratená karta, kľúč alebo mimoriadne upratovanie sa môžu účtovať podľa cenníka na recepcii."]},{"title":"Odchod","items":["Vráťte kartu a nechajte izbu čistú. Dátum odchodu vopred oznámte koordinátorovi a recepcii."]}],"version":"2026-09"},"uk":{"intro":"Ці правила роблять будівлю безпечною та спокійною для всіх. Їх порушення може призвести до штрафу або припинення проживання. (Шаблон на основі стандартних правил PRIMA — офіційний текст доступний на рецепції.)","sections":[{"title":"Доступ і особа","items":["У будівлі можуть проживати лише зареєстровані мешканці. При заселенні покажіть документ.","Картка доступу — особиста. Не позичайте її і не пропускайте нікого за собою через турнікет.","Про втрату картки негайно повідомте рецепцію."]},{"title":"Тиша","items":["22:00–06:00 — час тиші. Жодної гучної музики, телевізора чи зібрань у кімнатах і коридорах.","Багато мешканців сплять удень після нічних змін — не шуміть у будь-який час."]},{"title":"Відвідувачі","items":["Відвідувачі реєструються на рецепції з документом і можуть перебувати з 08:00 до 22:00.","Ночівля відвідувачів заборонена."]},{"title":"Кімнати","items":["У кімнатах заборонено курити, користуватися свічками, власними обігрівачами чи плитками.","Не переносьте меблі між кімнатами і не міняйте замки.","Про будь-яку несправність повідомте через додаток або на рецепції.","У робочі дні впускайте прибиральниць; цінні речі замикайте."]},{"title":"Кухня та чистота","items":["Готуйте лише на кухні. Мийте плиту та посуд одразу після використання.","Сортуйте сміття та виносьте його до контейнерів. У коридорах нічого не зберігати.","Продукти у спільному холодильнику підписуйте номером кімнати."]},{"title":"Безпека","items":["Не закривайте датчики диму та не блокуйте аварійні виходи.","У разі пожежі вийдіть із будівлі та телефонуйте 150 або 112.","Алкоголь у спільних приміщеннях заборонений. Пʼяна або агресивна поведінка припиняє проживання."]},{"title":"Пошкодження та оплата","items":["Про пошкодження повідомляйте негайно. Умисне пошкодження оплачується.","Втрачена картка, ключ або додаткове прибирання можуть оплачуватися за прейскурантом на рецепції."]},{"title":"Виїзд","items":["Поверніть картку та залиште кімнату чистою. Дату виїзду заздалегідь повідомте координатору та рецепції."]}],"version":"2026-09"}}'::jsonb)
  on conflict ((coalesce(property_id, '')), version) do update set texts = excluded.texts;
insert into public.rules (property_id, version, texts) values ('p_tarif', '1.0', '{"en":{"intro":"These rules keep the building safe and quiet for everyone. Breaking them can mean a fine or the end of your stay. Draft v1.0 for PRIMA sign-off.","items":[{"title":"Quiet hours","text":"22:00–06:00. Many neighbours work nights — keep corridors quiet at all hours."},{"title":"Smoking","text":"Only in the marked outdoor area. Never in rooms, kitchens, corridors or bathrooms."},{"title":"Visitors","text":"08:00–22:00, registered at reception with ID. No overnight guests."},{"title":"Your room","text":"Cleaned on weekdays. Keep the floor clear; personal items in your locker. Cleaners do not move belongings."},{"title":"Kitchen","text":"One per floor, shared. Clean after use, label food in the fridge, never leave the hob unattended."},{"title":"Alcohol","text":"Not in common areas — kitchens, corridors, reception, entrance. Drunk behaviour: warning, then contract review."},{"title":"Access card","text":"Personal — never lend it. Lost card: tell reception at once. A replacement is charged."},{"title":"Fire safety","text":"No cooking or open flame in rooms, no covered smoke detectors, no blocked corridors. Alarm → nearest exit → assembly point."},{"title":"Damage","text":"Report at once in the app. Intentional or negligent damage is charged to the resident."},{"title":"Waste","text":"Yellow: plastics, metals, cartons · Blue: paper · Green: glass · Black: mixed. Bins at the place shown by reception."},{"title":"Parking","text":"Registered cars only, marked places only. Register your plate at reception."},{"title":"Respect","text":"Zero tolerance for violence, harassment or discrimination. Report to reception or privately in the app."},{"title":"Check-out","text":"Return key/card, room inspected, leave by the check-out time on your last day."}],"version":"1.0"},"ru":{"intro":"Эти правила делают здание безопасным и спокойным для всех. Их нарушение может означать штраф или прекращение проживания. Проект v1.0 на утверждение PRIMA.","items":[{"title":"Часы тишины","text":"22:00–06:00. Многие соседи работают в ночные смены — в коридорах соблюдайте тишину в любое время."},{"title":"Курение","text":"Только в отмеченном месте на улице. Никогда в комнатах, кухнях, коридорах или ванных."},{"title":"Посетители","text":"08:00–22:00, регистрация на ресепшене с документом. Ночёвка гостей запрещена."},{"title":"Ваша комната","text":"Убирается в рабочие дни. Держите пол свободным; личные вещи — в шкафчике. Уборщицы не переносят вещи."},{"title":"Кухня","text":"Одна на этаж, общая. Убирайте после себя, подписывайте еду в холодильнике, никогда не оставляйте плиту без присмотра."},{"title":"Алкоголь","text":"Не в общих помещениях — кухни, коридоры, ресепшен, вход. Пьяное поведение: предупреждение, затем пересмотр договора."},{"title":"Карта доступа","text":"Личная — никогда не одалживайте. Потеряли — сразу сообщите на ресепшен. Замена платная."},{"title":"Пожарная безопасность","text":"Никакой готовки или открытого огня в комнатах, не закрывать датчики дыма, не загромождать коридоры. Сигнал → ближайший выход → место сбора."},{"title":"Ущерб","text":"Сразу сообщите в приложении. Умышленный или небрежный ущерб оплачивает жилец."},{"title":"Мусор","text":"Жёлтый: пластик, металл, тетрапак · Синий: бумага · Зелёный: стекло · Чёрный: смешанный. Контейнеры там, где покажет ресепшен."},{"title":"Парковка","text":"Только зарегистрированные автомобили, только на отмеченных местах. Зарегистрируйте номер на ресепшене."},{"title":"Уважение","text":"Нулевая терпимость к насилию, домогательствам и дискриминации. Сообщите на ресепшен или приватно в приложении."},{"title":"Выезд","text":"Верните ключ/карту, комнату проверят, выезд до установленного времени в последний день."}],"version":"1.0"},"sk":{"intro":"Tieto pravidlá udržiavajú budovu bezpečnú a pokojnú pre všetkých. Ich porušenie môže znamenať pokutu alebo ukončenie pobytu. Návrh v1.0 na schválenie PRIMA.","items":[{"title":"Nočný kľud","text":"22:00–06:00. Mnohí susedia pracujú na nočné — na chodbách buďte potichu v každú hodinu."},{"title":"Fajčenie","text":"Len na označenom mieste vonku. Nikdy v izbách, kuchyniach, na chodbách ani v kúpeľniach."},{"title":"Návštevy","text":"08:00–22:00, registrované na recepcii s dokladom. Prenocovanie návštev nie je dovolené."},{"title":"Vaša izba","text":"Upratuje sa v pracovné dni. Nechajte voľnú podlahu; osobné veci do skrinky. Upratovačky nehýbu s vecami."},{"title":"Kuchyňa","text":"Jedna na poschodí, spoločná. Po použití upracte, potraviny v chladničke označte, varič nikdy nenechávajte bez dozoru."},{"title":"Alkohol","text":"Nie v spoločných priestoroch — kuchyne, chodby, recepcia, vstup. Opité správanie: upozornenie, potom prehodnotenie zmluvy."},{"title":"Prístupová karta","text":"Osobná — nikdy ju nepožičiavajte. Stratu hneď nahláste na recepcii. Náhradná karta je spoplatnená."},{"title":"Požiarna bezpečnosť","text":"Žiadne varenie ani otvorený oheň v izbách, žiadne zakryté hlásiče dymu, žiadne zatarasené chodby. Alarm → najbližší východ → zhromaždisko."},{"title":"Škody","text":"Hneď nahláste v appke. Úmyselná alebo nedbanlivá škoda sa účtuje ubytovanému."},{"title":"Odpad","text":"Žltá: plasty, kovy, tetrapaky · Modrá: papier · Zelená: sklo · Čierna: zmesový. Nádoby na mieste, ktoré ukáže recepcia."},{"title":"Parkovanie","text":"Len registrované autá, len na vyznačených miestach. EČV nahláste na recepcii."},{"title":"Rešpekt","text":"Nulová tolerancia násilia, obťažovania a diskriminácie. Nahláste na recepcii alebo súkromne v appke."},{"title":"Odchod","text":"Vráťte kľúč/kartu, izba sa skontroluje, odchod do stanoveného času v posledný deň."}],"version":"1.0"},"uk":{"intro":"Ці правила роблять будівлю безпечною та спокійною для всіх. Їх порушення може означати штраф або припинення проживання. Проєкт v1.0 на затвердження PRIMA.","items":[{"title":"Години тиші","text":"22:00–06:00. Багато сусідів працюють у нічні зміни — у коридорах дотримуйтесь тиші в будь-який час."},{"title":"Куріння","text":"Лише на позначеному місці надворі. Ніколи в кімнатах, кухнях, коридорах чи ванних."},{"title":"Відвідувачі","text":"08:00–22:00, реєстрація на рецепції з документом. Ночівля гостей заборонена."},{"title":"Ваша кімната","text":"Прибирається в робочі дні. Тримайте підлогу вільною; особисті речі — у шафці. Прибиральниці не переносять речі."},{"title":"Кухня","text":"Одна на поверх, спільна. Прибирайте після себе, підписуйте їжу в холодильнику, ніколи не залишайте плиту без нагляду."},{"title":"Алкоголь","text":"Не в спільних приміщеннях — кухні, коридори, рецепція, вхід. Пʼяна поведінка: попередження, потім перегляд договору."},{"title":"Картка доступу","text":"Особиста — ніколи не позичайте. Загубили — негайно повідомте рецепцію. Заміна платна."},{"title":"Пожежна безпека","text":"Жодного готування чи відкритого вогню в кімнатах, не закривати датчики диму, не захаращувати коридори. Сигнал → найближчий вихід → місце збору."},{"title":"Пошкодження","text":"Негайно повідомте в додатку. Умисне або недбале пошкодження оплачує мешканець."},{"title":"Сміття","text":"Жовтий: пластик, метал, тетрапак · Синій: папір · Зелений: скло · Чорний: змішане. Контейнери там, де покаже рецепція."},{"title":"Парковка","text":"Лише зареєстровані авто, лише на позначених місцях. Зареєструйте номер на рецепції."},{"title":"Повага","text":"Нульова терпимість до насильства, домагань і дискримінації. Повідомте рецепцію або приватно в додатку."},{"title":"Виїзд","text":"Поверніть ключ/картку, кімнату перевірять, виїзд до встановленого часу в останній день."}],"version":"1.0"}}'::jsonb)
  on conflict ((coalesce(property_id, '')), version) do update set texts = excluded.texts;
